import time
visited = {}
def visit(loc):
    now = time.time()
    if loc in visited:
        return "revisit of %s (first seen %.0fs ago)" % (loc, now - visited[loc])
    visited[loc] = now
    return "first visit to " + loc
print(visit("db1")); print(visit("db1"))

