back, fwd, cur = [], [], "net"
def go(loc):
    global cur
    back.append(cur); fwd.clear(); cur = loc
def back_():
    global cur
    if back: fwd.append(cur); cur = back.pop()
go("arch1"); go("db1"); back_()
print("current:", cur, "| forward available:", fwd)

